7302: # own provider, the config's model) - several entries of different models leave the model unnamed;
7303: # a lineage without an engine takes its roster entry's, else codex. (D10) Only a value that cannot be
7304: # PARSED - the matcher's grammar, the shared character rule (Get-IdentityStringProblem) - is refused
7305: # (Error). (D11 / F32-4) A coordinator no roster entry matches is said, not refused: in_roster false.
7306: # (D12 / F32-5) `#n` that names no position here is no refusal: unresolved "#n" and a warning. {
7307: # Record - the ledger's `coordinator` {provider, model, engine, host, host_by (markers | path |
7308: # none), source (explicit | inferred | none), in_roster ($null without a roster or an identity),
7309: # unresolved ($null, or the `#n` that named nothing)}; Error ('' or the refusal); Warnings }.
7310: function Resolve-CoordinatorIdentity {
7311:     param([string]$Value, $Roster = $null, $Defaults = $null, [string]$ScriptPath = $PSScriptRoot)
7312:     $hint = Get-CoordinatorHostHint -ScriptPath $ScriptPath
7313:     if ($null -eq $Defaults) { $Defaults = [pscustomobject]@{ Provider = 'openai'; Model = '' } }
7314:     $r = [pscustomobject]@{ Record = $null; Error = ''; Warnings = [string[]]@() }
7315:     $hasRoster = [bool]($Roster -and $Roster.Exists)
7316:     $mk = {
7317:         param($P, $M, $E, [string]$Src, $InRoster, $Unresolved)
7318:         [pscustomobject]@{ provider = $P; model = $M; engine = $E; host = $hint.Host; host_by = $hint.By; source = $Src; in_roster = $InRoster; unresolved = $Unresolved }
7319:     }
7320:     $v = ([string]$Value).Trim()
7321:     if (-not $v) {
7322:         $r.Record = & $mk $null $null $null $(if ($hint.Host -ne 'unknown') { 'inferred' } else { 'none' }) $null $null
7323:         return $r
7324:     }
7325:     $m = ConvertFrom-ReviewerMatcher -Matcher $v
7326:     # (wave 29, item 9) a coordinator's model id (Claude family) may carry the 1M-context suffix
7327:     # (claude-opus-5-5[1m]): stripped - the comparison is on the model
7328:     if ($null -ne $m.Model -and ([string]$m.Model) -match '(?i)^claude-.*\[1m\]$') { $m.Model = ([string]$m.Model) -replace '(?i)\[1m\]$', '' }
7329:     $why = [string]$m.Error
7330:     if (-not $why -and $m.Kind -ne 'position') {
7331:         $pp = Get-IdentityStringProblem ([string]$m.Provider)
7332:         if ($pp) { $why = "the provider '$($m.Provider)' $pp" }
7333:         elseif ($null -ne $m.Model) { $mp = Get-IdentityStringProblem ([string]$m.Model); if ($mp) { $why = "the model '$($m.Model)' $mp" } }
7334:     }
7335:     if ($why) {
7336:         $r.Error = "CODEX_CONSULT_COORDINATOR='$v' cannot be used: $why - give '<provider> :: <model>' (optionally ' [<engine>]'), a roster position '#<n>' or a provider label; nothing was started."

